    zeroOrNegativeEffectsRetained: true,
    productDefaultsChanged: false,
    productLocksChanged: false,
    approvalChanged: false
  };
}

export async function loadRuntimeAdapter(modulePath) {
  const module = await import(pathToFileURL(modulePath).href);
  const createStore = module.createRuntimeMemoryStore ?? module.default?.createRuntimeMemoryStore ?? module.default;
  assert(typeof createStore === 'function', 'runtime module must export createRuntimeMemoryStore(options)');
  return { createStore };
}

export async function loadFixture(path) {
  return JSON.parse(await readFile(path, 'utf8'));
}

export function deterministicCaseSeed(seed, caseId, repetition) {
  return (seed + hashString(caseId) + repetition) >>> 0;
}

export const pairedAblationDefaults = Object.freeze({
  seed: DEFAULT_SEED,
  repetitions: DEFAULT_REPETITIONS,
  cases: DEFAULT_CASES,
  confidence: 0.95
});
