export interface RuntimeOperation {
  method: string;
  arguments?: unknown[];
}

export interface FixtureCase {
  id: string;
  insertions: RuntimeOperation[];
  attempts: RuntimeOperation[];
  expectedEvictionSetChanged?: boolean;
}

export interface PairedAblationFixture {
  schemaVersion: number;
  seed?: number;
  repetitions: number;
  cases: FixtureCase[];
  primaryMetric: {
    name: 'successRate' | 'passKRate' | 'latencyP50Ms' | 'latencyP95Ms' | 'tokensTotal' | 'falseBlocks' | 'safetyViolations';
    definition: string;
  };
  regressionBudget: Partial<Record<PrimaryMetricName, {
    minimum?: number;
    maximumDegradation?: number;
    direction: 'not-worse-than' | 'at-least';
  }>>;
}

export type PrimaryMetricName = PairedAblationFixture['primaryMetric']['name'];

export interface RuntimeMemoryStoreLike {
  clone(): RuntimeMemoryStoreLike | Promise<RuntimeMemoryStoreLike>;
  snapshot?(): Iterable<unknown> | Promise<Iterable<unknown>>;
  list?(): Iterable<unknown> | Promise<Iterable<unknown>>;
  entries?(): Iterable<unknown> | Promise<Iterable<unknown>>;
  [method: string]: unknown;
}

export interface RuntimeMemoryStoreAdapter {
  createStore(options: {
    condition: AblationCondition;
    seed: number;
    deterministic: true;
    eviction: { strategy: 'fifo' | 'type-aware' };
  }): RuntimeMemoryStoreLike | Promise<RuntimeMemoryStoreLike>;
}

export interface MetricEffect {
  estimate: number | null;
  standardError: number | null;
  cohensDz: number | null;
  confidence: number;
  lower: number | null;
  upper: number | null;
  direction: 'positive' | 'negative' | 'zero';
}

export interface PairedAblationReport {
  schemaVersion: 1;
  seed: number;
  repetitions: number;
  cases: number;
  confidence: number;
  component: {
    treatment: 'phase-4-type-aware-eviction';
    baseline: 'phase-4-fifo';
    leaveOneOut: true;
    reversible: true;
    safetyCritical: false;
    optIn: true;
    effectObserved: boolean;
  };
  conditions: Record<AblationCondition, {
    observations: number;
    successes: number;
    successRate: number | null;
    passK: number;
    passKRate: number | null;
    latencyMs: { p50: number | null; p95: number | null };
    tokens: { total: number; mean: number | null };
    falseBlocks: number;
    safetyViolations: number;
  }>;
  effects: Record<PrimaryMetricName, MetricEffect>;
  primaryMetric: {
    name: PrimaryMetricName;
    definition: string;
    effect: MetricEffect;
    regressionBudget: { minimum?: number; maximumDegradation?: number; direction: 'not-worse-than' | 'at-least' };
    withinBudget: boolean;
  };
  zeroOrNegativeEffectsRetained: boolean;
  productDefaultsChanged: false;
  productLocksChanged: false;
  approvalChanged: false;
}

export function runPairedAblation(options: {
  fixture: PairedAblationFixture;
  runtime: RuntimeMemoryStoreAdapter;
  seed?: number;
  confidence?: number;
}): Promise<PairedAblationReport>;

export function loadRuntimeAdapter(modulePath: string): Promise<RuntimeMemoryStoreAdapter>;
export function loadFixture(path: string): Promise<PairedAblationFixture>;
export function deterministicCaseSeed(seed: number, caseId: string, repetition: number): number;

export const pairedAblationDefaults: Readonly<{
  seed: number;
  repetitions: number;
  cases: number;
  confidence: number;
}>;
