{"edits":[{"path":"scripts/lib/paired-ablation.mjs","content":"import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

const DEFAULT_SEED = 20240229;
const DEFAULT_REPETITIONS = 3;
const DEFAULT_CASES = 20;

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function quantile(values, q) {
  const sorted = [...values].sort((a, b) => a - b);
  if (sorted.length === 0) return null;
  const index = (sorted.length - 1) * q;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  if (lower === upper) return sorted[lower];
  return sorted[lower] + (sorted[upper] - sorted[lower]) * (index - lower);
}

function mean(values) {
  return values.length === 0 ? null : values.reduce((a, b) => a + b, 0) / values.length;
}

function pairedDifference(treatment, baseline) {
  assert(treatment.length === baseline.length, 'paired observations have different lengths');
  return treatment.map((value, index) => value - baseline[index]);
}

function standardDeviation(values) {
  if (values.length < 2) return 0;
  const average = mean(values);
  return Math.sqrt(values.reduce((sum, value) => sum + (value - average) ** 2, 0) / (values.length - 1));
}

function pairedEffect(differences) {
  const average = mean(differences);
  const standardDeviation = standardDeviation(differences);
  return {
    estimate: average,
    standardError: standardDeviation / Math.sqrt(differences.length),
    cohensDz: standardDeviation === 0 ? (average === 0 ? 0 : null) : average / standardDeviation
  };
}

function normalCriticalValue(confidence) {
  const probabilities = [
    [0.8, 1.2815515655446004],
    [0.9, 1.6448536269514722],
    [0.95, 1.959963984540054],
    [0.98, 2.3263478740408408],
    [0.99, 2.5758293035489004]
  ];
  const match = probabilities.find(([probability]) => probability === confidence);
  assert(match, `unsupported confidence level: ${confidence}`);
  return match[1];
}

function normalInterval(differences, confidence) {
  const effect = pairedEffect(differences);
  const halfWidth = normalCriticalValue(confidence) * effect.standardError;
  return {
    ...effect,
    confidence,
    lower: effect.estimate === null ? null : effect.estimate - halfWidth,
    upper: effect.estimate === null ? null : effect.estimate + halfWidth
  };
}

function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state += 0x6d2b79f5;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}\n
function hashString(value) {
  let hash = 2166136261;
  for (const character of String(value)) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function stableKey(value) {
  return typeof value === 'string' ? value : JSON.stringify(value);
}

function snapshotKeys(store) {
  const snapshot = typeof store.snapshot === 'function'
    ? store.snapshot()
    : typeof store.list === 'function'
      ? store.list()
      : typeof store.entries === 'function'
        ? store.entries()
        : null;
  assert(snapshot !== null, 'runtime store must expose snapshot(), list(), or entries()');
  const values = Array.isArray(snapshot) ? snapshot : Array.from(snapshot.values?.() ?? snapshot);
  return values.map((entry) => {
    if (entry && typeof entry === 'object') return stableKey(entry.key ?? entry.id ?? entry.memoryId ?? entry);
    return stableKey(entry);
  }).sort();
}

async function invoke(store, operation) {
  const method = operation.method;
  assert(typeof store[method] === 'function', `runtime store does not implement ${method}()`);
  return store[method](...operation.arguments);
}

function readBoolean(result, field) {
  if (result && typeof result === 'object' && field in result) return Boolean(result[field]);
  return Boolean(result);
}

function readNumber(result, field, fallback = 0) {
  if (result && typeof result === 'object' && field in result) return Number(result[field]);
  return Number(result ?? fallback);
}

function cloneStore(store) {
  assert(typeof store.clone === 'function', 'runtime store must expose clone() for isolated case evaluation');
  return store.clone();
}

async function executeCase(runtime, fixtureCase, condition, repetition, seed) {
  const store = await runtime.createStore({
    condition,
    seed,
    deterministic: true,
    eviction: condition === 'treatment'
      ? { strategy: 'type-aware' }
      : { strategy: 'fifo' }
  });
  assert(store, `runtime.createStore() returned no store for ${condition}`);
  const inserted = [];
  for (const operation of fixtureCase.insertions) {
    await invoke(store, operation);
    inserted.push(stableKey(operation.arguments[0]?.key ?? operation.arguments[0]?.id ?? operation.arguments[0]));
  }
  const retained = snapshotKeys(store);
  const evictionSetChanged = fixtureCase.expectedEvictionSetChanged === true;
  assert(
    !evictionSetChanged || retained.length !== inserted.length || retained.some((key) => !inserted.includes(key)),
    `component effect was not observed for case ${fixtureCase.id}`
  );
  let successes = 0;
  let falseBlocks = 0;
  let safetyViolations = 0;
  const latencies = [];
  const tokens = [];
  const attempts = [];
  for (const attempt of fixtureCase.attempts) {
    const start = performance.now();
    const result = await invoke(store, attempt);
    latencies.push(performance.now() - start);
    successes += readBoolean(result, 'success') ? 1 : 0;
    falseBlocks += readBoolean(result, 'falseBlock') ? 1 : 0;
    safetyViolations += readBoolean(result, 'safetyViolation') ? 1 : 0;
    tokens.push(readNumber(result, 'tokens', readNumber(result, 'tokenCount', 0)));
    attempts.push(result);
  }
  const success = successes === fixtureCase.attempts.length;\n  const passK = fixtureCase.attempts.every((_, index) => readBoolean(attempts[index], 'success'));
  return {
    caseId: fixtureCase.id,
    condition,
    repetition,
    success,
    passK,
    latencyMs: latencies,
    tokens,
    falseBlocks,
    safetyViolations,
    retained,
    inserted
  };
}

function pairRecords(baseline, treatment) {
  const treatmentByKey = new Map(treatment.map((record) => [`${record.caseId}:${record.repetition}`, record]));
  return baseline.map((base) => {
    const treated = treatmentByKey.get(`${base.caseId}:${base.repetition}`);
    assert(treated, `missing paired treatment observation for ${base.caseId}:${base.repetition}`);
    return { baseline: base, treatment: treated };
  });
}

function summarizeCondition(records) {
  const latencies = records.flatMap((record) => record.latencyMs);
  const tokens = records.flatMap((record) => record.tokens);
  return {
    observations: records.length,
    successes: records.filter((record) => record.success).length,
    successRate: mean(records.map((record) => record.success ? 1 : 0)),
    passK: records.filter((record) => record.passK).length,
    passKRate: mean(records.map((record) => record.passK ? 1 : 0)),
    latencyMs: {
      p50: quantile(latencies, 0.5),
      p95: quantile(latencies, 0.95)
    },
    tokens: {
      total: tokens.reduce((sum, value) => sum + value, 0),
      mean: mean(tokens)
    },
    falseBlocks: records.reduce((sum, record) => sum + record.falseBlocks, 0),
    safetyViolations: records.reduce((sum, record) => sum + record.safetyViolations, 0)
  };
}

function metricDifferences(pairs, selector) {
  return pairs.map(({ baseline, treatment }) => selector(treatment) - selector(baseline));
}

function effectReport(differences, confidence) {
  const interval = normalInterval(differences, confidence);
  return {
    ...interval,
    direction: interval.estimate > 0 ? 'positive' : interval.estimate < 0 ? 'negative' : 'zero'
  };
}

function validateFixture(fixture) {
  assert(Array.isArray(fixture.cases), 'fixture.cases must be an array');
  assert(fixture.cases.length >= DEFAULT_CASES, `fixture must contain at least ${DEFAULT_CASES} cases`);
  assert(fixture.repetitions >= DEFAULT_REPETITIONS, `fixture must contain at least ${DEFAULT_REPETITIONS} repetitions`);
  assert(fixture.primaryMetric && fixture.primaryMetric.name, 'fixture.primaryMetric is required');
  assert(fixture.regressionBudget, 'fixture.regressionBudget is required');
  const ids = new Set();
  for (const fixtureCase of fixture.cases) {
    assert(fixtureCase.id && !ids.has(fixtureCase.id), 'case ids must be present and unique');
    ids.add(fixtureCase.id);
    assert(Array.isArray(fixtureCase.insertions) && fixtureCase.insertions.length > 0, `${fixtureCase.id} has no insertions`);
    assert(Array.isArray(fixtureCase.attempts) && fixtureCase.attempts.length > 0, `${fixtureCase.id} has no attempts`);
  }
}

/**
 * Run a paired, leave-one-out ablation against an injected RuntimeMemoryStore adapter.
 * The adapter must return stores supporting snapshot/list/entries, clone, and the
 * operations named by the fixture. createStore must honor the supplied eviction
 * strategy; no adapter supplied here can change product defaults or approval.
 */
export async function runPairedAblation({ fixture, runtime, seed = DEFAULT_SEED, confidence = 0.95 }) {
  validateFixture(fixture);
  assert(runtime && typeof runtime.createStore === 'function', 'a RuntimeMemoryStore adapter is required');
  const baseline = [];
  const treatment = [];
  for (const fixtureCase of fixture.cases) {
    for (let repetition = 0; repetition < fixture.repetitions; repetition += 1) {
      const pairedSeed = (seed + hashString(fixtureCase.id) + repetition) >>> 0;
      baseline.push(await executeCase(runtime, fixtureCase, 'baseline', repetition, pairedSeed));
      treatment.push(await executeCase(runtime, fixtureCase, 'treatment', repetition, pairedSeed));
    }
  }
  const pairs = pairRecords(baseline, treatment);
  const differences = {
    successRate: metricDifferences(pairs, (record) => record.success ? 1 : 0),
    passKRate: metricDifferences(pairs, (record) => record.passK ? 1 : 0),
    latencyP50Ms: metricDifferences(pairs, (record) => quantile(record.latencyMs, 0.5) ?? 0),
    latencyP95Ms: metricDifferences(pairs, (record) => quantile(record.latencyMs, 0.95) ?? 0),
    tokensTotal: metricDifferences(pairs, (record) => record.tokens.reduce((sum, value) => sum + value, 0)),
    falseBlocks: metricDifferences(pairs, (record) => record.falseBlocks),
    safetyViolations: metricDifferences(pairs, (record) => record.safetyViolations)
  };
  const effects = Object.fromEntries(Object.entries(differences).map(([name, values]) => [name, effectReport(values, confidence)]));
  const componentObserved = pairs.some(({ baseline: base, treatment: treated }) => stableKey(base.retained) !== stableKey(treated.retained));
  assert(componentObserved, 'baseline and treatment retained/evicted sets did not differ in any paired observation');
  const primaryName = fixture.primaryMetric.name;
  assert(primaryName in effects, `primary metric ${primaryName} is not supported`);
  const primaryEffect = effects[primaryName];
  const budget = fixture.regressionBudget[primaryName];
  assert(budget !== undefined, `regression budget for primary metric ${primaryName} is missing`);
  return {
    schemaVersion: 1,
    seed,
    repetitions: fixture.repetitions,
    cases: fixture.cases.length,
    confidence,
    component: {
      treatment: 'phase-4-type-aware-eviction',
      baseline: 'phase-4-fifo',
      leaveOneOut: true,
      reversible: true,
      safetyCritical: false,
      optIn: true,
      effectObserved: componentObserved
    },
    conditions: {
      baseline: summarizeCondition(baseline),
      treatment: summarizeCondition(treatment)
    },
    effects,
    primaryMetric: {
      name: primaryName,
      definition: fixture.primaryMetric.definition,
      effect: primaryEffect,
      regressionBudget: budget,
      withinBudget: budget.direction === 'not-worse-than'
        ? primaryEffect.lower >= budget.maximumDegradation
        : primaryEffect.lower >= budget.minimum
    },
    zeroOrNegativeEffectsRetained: true,
    productDefaultsChanged: false,
    productLocksChanged: false,
    approvalChanged: false
  };
}

export async function loadRuntimeAdapter(modulePath) {
  const module = await import(pathToFileURL(modulePath).href);
  const createStore = module.createRuntimeMemoryStore ?? module.default?.createRuntimeMemoryStore ?? module.default;
  assert(typeof createStore === 'function', 'runtime module must export createRuntimeMemoryStore(options)');
  return { createStore };
}

export async function loadFixture(path) {
  return JSON.parse(await readFile(path, 'utf8'));
}

export function deterministicCaseSeed(seed, caseId, repetition) {
  return (seed + hashString(caseId) + repetition) >>> 0;
}

export const pairedAblationDefaults = Object.freeze({
  seed: DEFAULT_SEED,
  repetitions: DEFAULT_REPETITIONS,
  cases: DEFAULT_CASES,
  confidence: 0.95
});
