export async function runPairedAblation({ fixture, runtime, seed = DEFAULT_SEED, confidence = 0.95 }) {
  validateFixture(fixture);
  assert(runtime && typeof runtime.createStore === 'function', 'a RuntimeMemoryStore adapter is required');
  const baseline = [];
  const treatment = [];
  for (const fixtureCase of fixture.cases) {
    for (let repetition = 0; repetition < fixture.repetitions; repetition += 1) {
      const pairedSeed = (seed + hashString(fixtureCase.id) + repetition) >>> 0;
      baseline.push(await executeCase(runtime, fixtureCase, 'baseline', repetition, pairedSeed));
      treatment.push(await executeCase(runtime, fixtureCase, 'treatment', repetition, pairedSeed));
    }
